<?php use App\Core\Auth; use App\Core\Csrf; use App\Core\View; ?>
<div class="page-header"><h1>Caixa</h1><a class="button primary" href="/pos">Ir ao PDV</a></div>
<?php if(!$current): ?>
<div class="panel"><div class="panel-header">Abertura</div><div class="panel-body"><form method="post" action="/cash/open"><?= Csrf::field() ?>
<div class="grid three"><div class="field"><label>Caixa</label><select name="register_id" required><option value="">Selecione uma opção...</option><?php foreach($registers as $r): ?><option value="<?= (int)$r['id'] ?>"><?= View::e($r['name']) ?></option><?php endforeach ?></select></div><div class="field"><label>Fundo inicial</label><input name="amount" inputmode="decimal" data-mask="money" value="0,00" required placeholder="Ex.: 150,00"></div><div class="field"><label>Observação</label><input name="notes" placeholder="Ex.: Abertura do turno da manhã"></div></div><button class="primary">Abrir caixa</button></form></div></div>
<?php else: ?>
<div class="grid three"><div class="stat"><span>Caixa</span><strong><?= View::e($current['register_name']) ?></strong></div><div class="stat"><span>Fundo</span><strong>R$ <?= number_format($totals['opening'],2,',','.') ?></strong></div><div class="stat"><span>Esperado agora</span><strong>R$ <?= number_format($totals['expected'],2,',','.') ?></strong></div></div>
<?php if(Auth::can('cash.move')): ?><div class="panel"><div class="panel-header">Suprimento / sangria</div><div class="panel-body"><form method="post" action="/cash/move"><?= Csrf::field() ?><div class="grid three"><div class="field"><label>Tipo</label><select name="type"><option value="supply">Suprimento</option><option value="withdrawal">Sangria</option></select></div><div class="field"><label>Valor</label><input name="amount" data-mask="money" required placeholder="Ex.: 80,00"></div><div class="field"><label>Justificativa</label><input name="reason" minlength="5" required placeholder="Ex.: Sangria para o cofre"></div></div><button>Registrar</button></form></div></div><?php endif ?>
<?php if(Auth::can('cash.close')): ?><div class="panel"><div class="panel-header">Fechamento</div><div class="panel-body"><form method="post" action="/cash/close"><?= Csrf::field() ?><div class="grid two"><div class="field"><label>Dinheiro contado</label><input name="counted" data-mask="money" required placeholder="Ex.: 350,00"></div><div class="field"><label>Justificativa (obrigatória se divergir)</label><input name="reason" placeholder="Ex.: Informe o motivo se o valor divergir"></div></div><button class="danger">Fechar caixa</button></form></div></div><?php endif ?>
<?php endif ?>
<div class="panel"><div class="panel-header">Histórico</div><div class="panel-body table-wrap"><table><thead><tr><th>Caixa</th><th>Operador</th><th>Abertura</th><th>Fechamento</th><th class="num">Esperado</th><th class="num">Contado</th><th class="num">Diferença</th><th>Justificativa</th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?= View::e($h['register_name']) ?></td><td><?= View::e($h['user_name']) ?></td><td><?= View::e($h['opened_at']) ?></td><td><?= View::e($h['closed_at']??'Aberto') ?></td><td class="num"><?= $h['expected_cash']===null?'—':'R$ '.number_format((float)$h['expected_cash'],2,',','.') ?></td><td class="num"><?= $h['counted_cash']===null?'—':'R$ '.number_format((float)$h['counted_cash'],2,',','.') ?></td><td class="num"><?= $h['difference_amount']===null?'—':'R$ '.number_format((float)$h['difference_amount'],2,',','.') ?></td><td><?= View::e($h['closing_reason']??'') ?></td></tr><?php endforeach ?></tbody></table></div></div>
